mapper.select:
/* AppAuth01Mapper.selectUserId */
SELECT A.USER_ID
  FROM TB_USER A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.USER_CD  = #{userCd}

mapper.delete:
/* AppAuth01Mapper.deleteMyPresetSteps */
DELETE D
  FROM TB_APRV_LINE_PRESET_D D
  INNER JOIN TB_APRV_LINE_PRESET P
    ON  P.CMPNY_CD  = D.CMPNY_CD
    AND P.PRESET_ID = D.PRESET_ID
 WHERE P.CMPNY_CD = #{cmpnyCd}
   AND P.USER_CD  = #{userCd}

/* AppAuth01Mapper.deleteMyPresetMasters */
DELETE FROM TB_APRV_LINE_PRESET
 WHERE CMPNY_CD = #{cmpnyCd}
   AND USER_CD  = #{userCd}

mapper.insert:
/* AppAuth01Mapper.insertDelUser */
INSERT INTO TB_DEL_USER (
      CMPNY_CD, USER_ID, USER_NM, INSERT_NO, INSERT_DATE
) VALUES (
      #{cmpnyCd}, #{userId}, #{maskedUserNm}, #{insertNo}, NOW()
)
